import{_ as l,l as n,o as t,c as i,v as e,p as s,x as r,d as _,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"token 级奖励塑形","description":"","frontmatter":{"title":"token 级奖励塑形","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/token-level-reward.md","filePath":"llm/token-level-reward.md","lastUpdated":1789023840000}'),m={name:"llm/token-level-reward.md"};function h(c,a,A,P,k,E){const o=n("Mermaid");return t(),i("div",null,[a[1]||(a[1]=e('<h1 id="token-级奖励塑形" tabindex="-1">token 级奖励塑形 <a class="header-anchor" href="#token-级奖励塑形" aria-label="Permalink to &quot;token 级奖励塑形&quot;">​</a></h1><div class="epigraph"><p>序列只有终点一个标量时，前几百个 token 的优势近乎零；塑形是把信用挪到真正决策的位置，而不是另造一个偏好模型。</p><footer>—— 对照 Sutton 的奖励塑形；过程奖励与逐步 KL 是语言模型里最常用的两种稠密化</footer></div><p><a href="/llm/multi-objective-reward">上一课</a>得到一个序列标量 \\(r(x,y)\\)。接到 <a href="/llm/ppo-llm">PPO</a> 时，动作却是逐 token 的。缺口是：<strong>稀疏终点让中间步的梯度消失，模型只改结尾套话。</strong> 本课写 token 级塑形：逐步 KL、过程分、格式分播到位置上。不重推 clip。下一单元从 GAE 的 \\(\\lambda\\) 接着讲如何把这些逐步奖励变成优势。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>轨迹长度数百到数千。若只在 EOS 放 \\(r\\)，REINFORCE 的信用分配把同一个回报赋给所有 token，方差大；配合价值函数时，早期 \\(V\\) 也难学。InstructGPT 的逐步 KL 已经是一种塑形：每步减 \\(\\beta\\log(\\pi_\\theta/\\pi_{\\mathrm{ref}})\\)，中间 token 立刻有非零项。Lightman 的 PRM 把逐步对错变成更语义化的稠密奖励。<a href="/llm/grpo">GRPO</a> 默认整条共享一个 \\(\\hat A_i\\)，等于不做逐步塑形。</p><p>乱塑形会改变最优策略。Ng、Harada、Russell 的势函数塑形保证最优策略不变；随便把「看见关键词 +0.1」加进中间步，会教会刷词。本课只允许与任务同构的稠密信号：KL、过程合法、格式锚点。</p><h3 id="广播不是塑形" tabindex="-1">广播不是塑形 <a class="header-anchor" href="#广播不是塑形" aria-label="Permalink to &quot;广播不是塑形&quot;">​</a></h3><p>把序列 \\(r\\) 均摊到每个 token，或只放在最后一个 token，是实现约定，不增加信息。塑形要新的逐步可观测量 \\(r_t\\)。DAPO 的 token 级<strong>损失平均</strong>也不是塑形：它改的是梯度测度，奖励仍是序列标量。</p><p><span class="marginnote">PRM 的 \\(q_t\\) 当 \\(r_t\\) 时，归约（min / 乘积）与逐步奖励是两条用法。前者给 BoN，后者给 RL。不要混。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>逐步奖励常见三层：</p> \\[r_t = -\\beta \\log\\frac{\\pi_\\theta(a_t\\mid s_t)}{\\pi_{\\mathrm{ref}}(a_t\\mid s_t)} +\\gamma_{\\mathrm{p}}\\, q_t +\\mathbf{1}[t=T]\\, R_{\\mathrm{seq}}. \\]<p>\\(q_t\\) 来自 <a href="/llm/process-supervision">过程监督</a> 或规则（是否仍在 boxed 前、是否非法结束）。\\(R_{\\mathrm{seq}}\\) 是 RM、校验器或多目标合成。实现上 \\(r_t\\) 进入 GAE 或直接当逐步优势的素材。KL 已在奖励里就不要在损失里再加一份 \\(\\beta\\)。</p>',13)),(t(),s(d,null,{default:r(()=>[p(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEQ%5B%22%E5%BA%8F%E5%88%97%20R%22%5D%20--%3E%20LAST%5B%22%E7%BB%88%E7%82%B9%E9%A1%B9%22%5D%0A%20%20KL%5B%22%E9%80%90%E6%AD%A5%20KL%22%5D%20--%3E%20RT%5B%22r_t%22%5D%0A%20%20PRM%5B%22%E9%80%90%E6%AD%A5%20q_t%22%5D%20--%3E%20RT%0A%20%20LAST%20--%3E%20RT%0A%20%20RT%20--%3E%20GAE%5B%22GAE%20%2F%20%E9%80%90%E6%AD%A5%E4%BC%98%E5%8A%BF%22%5D%0A%20%20GAE%20--%3E%20PPO%5B%22token%20%E7%BA%A7%20PPO%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[_(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>格式锚：只在抽取失败的位置给负分，而不是每步扣。否则模型学会极短回答以减少扣分次数。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>稠密 \\(r_t\\) 降低方差，让早期决策（选哪条引理、是否调用工具）立刻看到反馈。代价是偏差：PRM 错标会把错误过程当正奖励。势函数观点：若 \\(q_t = \\Phi(s_{t+1})-\\Phi(s_t)\\)，最优策略不变；PRM 不是势，最优会变——这是有意的，我们就是要过程合法的策略。</p><p>GRPO 若仍整条共享 \\(\\hat A\\)，塑形的逐步差会被抹平。要 token 级信用，需逐步 \\(r_t\\) 或改 PPO-critic。这是本课与群体方法的接口，不是否定 GRPO。</p><p><span class="marginnote">长度惩罚按 token 扣还是只在超长后扣，会剧烈改变平均长度。与后课过长过滤一起设计，不要两处各扣一次。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>开放偏好几乎没有可靠 \\(q_t\\)，只保留逐步 KL + 终点 RM。可验证域优先终点校验器，过程项用轻量规则或小 PRM。塑形过度会让策略优化塑形项、忽略 \\(R_{\\mathrm{seq}}\\)，又一条 Goodhart。下一课用 GAE 的 \\(\\lambda\\) 在偏差与方差之间插值，承接这里的逐步 \\(r_t\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>稀疏序列奖励让早期 token 梯度近零；塑形引入逐步可观测量。</li><li>合法塑形：逐步 KL、过程分、格式锚；关键词刷分会改最优策略。</li><li>广播终点分 / token 级损失平均都不是塑形。</li><li>GRPO 默认序列优势，逐步塑形需显式 \\(r_t\\)。</li><li>出处：Sutton 塑形；Schulman GAE 的输入；Ouyang 逐步 KL；Lightman PRM。</li></ul>',9))])}const R=l(m,[["render",h]]);export{f as __pageData,R as default};
